import java.util.*;
public class BTreeEducational { static final int T=2; static class Node{ArrayList<Integer> keys=new ArrayList<Integer>();ArrayList<Node> child=new ArrayList<Node>();boolean leaf=true;} Node root=new Node(); public boolean contains(int k){return search(root,k);} boolean search(Node x,int k){int i=0;while(i<x.keys.size()&&k>x.keys.get(i))i++;if(i<x.keys.size()&&k==x.keys.get(i))return true;return !x.leaf&&search(x.child.get(i),k);} public void insert(int k){if(root.keys.size()==2*T-1){Node s=new Node();s.leaf=false;s.child.add(root);split(s,0);root=s;}nonFull(root,k);} void split(Node p,int i){Node y=p.child.get(i),z=new Node();z.leaf=y.leaf;int mid=y.keys.get(T-1);z.keys.add(y.keys.remove(T));y.keys.remove(T-1);if(!y.leaf){z.child.add(y.child.remove(T));z.child.add(y.child.remove(T));}p.keys.add(i,mid);p.child.add(i+1,z);System.out.println("split promoted median "+mid);} void nonFull(Node x,int k){int i=x.keys.size()-1;if(x.leaf){x.keys.add(0);while(i>=0&&k<x.keys.get(i)){x.keys.set(i+1,x.keys.get(i));i--;}x.keys.set(i+1,k);}else{while(i>=0&&k<x.keys.get(i))i--;i++;if(x.child.get(i).keys.size()==2*T-1){split(x,i);if(k>x.keys.get(i))i++;}nonFull(x.child.get(i),k);}} public static void run(){BTreeEducational b=new BTreeEducational();for(int x:new int[]{8,9,10,11,15,20,17})b.insert(x);System.out.println("B-tree contains 15="+b.contains(15));System.out.println("Deletion concept: borrow from sibling, merge nodes, and shrink an empty root.\n");} public static void main(String[] args){run();}}
